      const existing = await readObject(STORAGE_REFERENCE_BUDGET_MIGRATION_KEY, {});
      if (existing?.version === REFERENCE_BUDGET_MIGRATION_VERSION) return existing;
      if (legacyMarker?.referenceBudgetVersion === REFERENCE_BUDGET_MIGRATION_VERSION) {
        const adopted = {
          version: REFERENCE_BUDGET_MIGRATION_VERSION,
          migration: legacyMarker.referenceBudgetMigration || { migrated: false, reason: 'adopted_from_v2_marker' },
          migratedAt: legacyMarker.referenceBudgetMigratedAt || new Date().toISOString(),
          source: 'adopted_from_v2_marker'
        };
        if (!await writeObject(STORAGE_REFERENCE_BUDGET_MIGRATION_KEY, adopted)) throw new Error('reference_budget_v3_marker_write_failed');
        return adopted;
      }
      const migration = await migrateReferenceBudgetCaps();
      const marker = {
        version: REFERENCE_BUDGET_MIGRATION_VERSION,
        migration,
        migratedAt: new Date().toISOString(),
        source: 'v0.24.x'
      };
      if (!await writeObject(STORAGE_REFERENCE_BUDGET_MIGRATION_KEY, marker)) throw new Error('reference_budget_v3_marker_write_failed');
      return marker;
